local config = {
  ui_story_5003_50030101_1_dialog_content = "PlayerName, kami diserang oleh segerombolan Eclipsites! Kita tidak bisa tinggal serendah ini!",
  ui_story_5003_50030101_2_dialog_content = "Apa yang—!? Kita punya Eclipsites di seluruh Colossus! Ada terlalu banyak dari mereka!",
  ui_story_5003_50030101_3_dialog_content = "Lupakan pendaratan untuk saat ini... Mari kita langsung menuju Cloud Mountain!",
  ui_story_5003_50030101_4_dialog_content = "Mengerti! Bersiap-siap untuk lepas landas!",
  ui_story_5003_50030101_5_dialog_content = "Saya minta maaf. Seluruh kekacauan ini adalah salahku.",
  ui_story_5003_50030101_6_dialog_content = "Ini bukan salahmu, Hiiro.",
  ui_story_5003_50030101_7_dialog_content = "<color=#e8d9bb>Tiga hari yang lalu.</color>",
  ui_story_5003_50030101_8_dialog_content = "Uh-oh... PlayerName, Komandan Hiiro datang mencari kita!",
  ui_story_5003_50030101_9_dialog_content = "Apa masalahnya, Vice? Mengapa Anda begitu gelisah?",
  ui_story_5003_50030101_10_dialog_content = "Sejujurnya, saya belum pernah melihat Komandan Hiiro meminta bantuan untuk masalah pribadi sebelumnya. Ini pasti serius...",
  ui_story_5003_50030101_11_dialog_content = "Aku minta maaf karena memaksakanmu seperti ini. Bisakah Anda memberi saya bagian di Colossus dan membawa saya ke tujuan?",
  ui_story_5003_50030101_12_dialog_content = "Tentu saja... Tapi bolehkah aku bertanya tentang apa semua ini?",
  ui_story_5003_50030101_13_dialog_content = "<color=#FFB400>Sesuatu yang aneh</color> telah terjadi pada Sakae Blade-ku. Saya ingin menyelidiki masalah ini.",
  ui_story_5003_50030101_14_dialog_content = "Saya tidak punya banyak waktu luang, jadi saya berharap untuk segera memulai penyelidikan.",
  ui_story_5003_50030101_15_dialog_content = "Apakah itu benar-benar mendesak? Saya berharap untuk membuat beberapa penyesuaian pada Colossus sebelum lepas landas...",
  ui_story_5003_50030101_16_dialog_content = "Maksud saya, tidak mudah bagi seorang Komandan Legiun untuk mengajukan cuti seperti ini.",
  ui_story_5003_50030101_17_dialog_content = "Yah, itu hanya perawatan rutin, jadi kurasa tidak apa-apa jika aku menundanya untuk saat ini. Jadi, ke mana Anda ingin pergi?",
  ui_story_5003_50030101_18_dialog_content = "Ke timur... Ke Gunung Awan.",
  ui_story_5003_50030101_19_dialog_content = "Negeri yang diselimuti salju sepanjang tahun, tempat bunga sakura sering mekar, menyuntikkan warna ke lanskap putih bersih...",
  ui_story_5003_50030101_x19_dialog_content = "Kampung halaman saya.",
  ui_story_5003_50030101_S19_dialog_content = "Gumpalan spiral dan naik di Timur\nDi puncak gunung yang jauh\nGunung Awan, di mana ribuan tahun yang lalu\nSeorang dewa melakukan pemberian harta karun\nUntuk melindungi wilayah dari murka Eclipsite\nMeskipun kedamaian yang dibawanya tidak akan pernah bertahan lama\nSekarang ketegangan meningkat dan faksi meningkat\nHarta itu menjadi mangsa mata yang tamak\nSaat cengkeraman kekacauan mencengkeram tanah\nFajar perang sudah dekat\n— Pemandangan dari Gunung Awan",
  ui_story_5003_50030101_20_dialog_content = "Ini Cloud Mountain... Lihat semua kabin besar ini!",
  ui_story_5003_50030101_21_dialog_content = "Saya tahu sangat menyenangkan berada di tempat baru, tapi serius, fokus!",
  ui_story_5003_50030101_22_dialog_content = "Ini adalah Gunung Awan yang legendaris...? Apa yang Anda katakan tentang tempat ini terakhir kali?",
  ui_story_5003_50030101_23_dialog_content = "Cloud Mountain adalah sebuah kota di sebuah pulau di Timur Jauh. Ini selalu tertutup salju dan terkenal dengan sumber air panas.",
  ui_story_5003_50030101_24_dialog_content = "Wilayah ini dikenal dengan bunga sakura selama musim salju. Salju menutupi cabang-cabang pohon sakura seperti awan, itulah sebabnya ia juga disebut Gunung Cloud Blossom!",
  ui_story_5003_50030101_25_dialog_content = "Ya itu betul. Itu persis apa yang ingin saya lihat ...",
  ui_story_5003_50030101_26_dialog_content = "Tapi bagaimana dengan segerombolan besar Eclipsites di luar Cloud Mountain? Mereka menerkam kita bahkan sebelum kita bisa mendarat!",
  ui_story_5003_50030101_27_dialog_content = "Eclipsites cukup aktif di sekitar Cloud Mountain, tapi sebelumnya tidak banyak di sekitar sini.",
  ui_story_5003_50030101_28_dialog_content = "Mungkin ada peningkatan mendadak dalam aktivitas Eclipsite seperti Astra lainnya?",
  ui_story_5003_50030101_29_dialog_content = "Hmm, mungkin. Tapi jangan khawatir, mereka tidak akan mengganggu kita.",
  ui_story_5003_50030101_30_dialog_content = "Kenapa?",
  ui_story_5003_50030101_31_dialog_content = "Legenda mengatakan bahwa <color=#FFB400>Cloud Mountain dilindungi oleh penghalang magis</color>. Eclipsites takut akan kekuatannya dan tidak berani masuk.",
  ui_story_5003_50030101_32_dialog_content = "Gaah... Graaah... Astaga!",
  ui_story_5003_50030101_33_dialog_content = "Hiiro... Apakah Anda baru saja mengatakan bahwa Eclipsites tidak berani masuk?",
  ui_story_5003_50030101_34_dialog_content = "Ya, Eclipsites tidak akan mengambil inisiatif untuk menyerang Cloud Mountain saat dilindungi oleh penghalang, kecuali...",
  ui_story_5003_50030101_35_dialog_content = "Kecuali kita membawa Eclipsites itu bersama kita!?",
  ui_story_5003_50030101_36_dialog_content = "*Meraung*",
  ui_story_5003_50030101_37_dialog_content = "Sekarang itu sedikit lebih dari yang bisa kita tangani, bukan begitu!?",
  ui_story_5003_50030101_38_dialog_content = "Hati-hati, Komandan Hiiro!",
  ui_story_5003_50030101_39_dialog_content = "Graaah—!",
  ui_story_5003_50030101_40_dialog_content = "Ugh!",
  ui_story_5003_50030101_41_dialog_content = "Menyingkir!",
  ui_story_5003_50030101_42_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030101_43_dialog_content = "Apa artinya ini, membawa Eclipsites ini ke sini pagi-pagi sekali...?",
  ui_story_5003_50030101_44_dialog_content = "Ini semua salah paham. Kami dikepung oleh Eclipsites di luar dan tidak punya pilihan selain masuk.",
  ui_story_5003_50030101_45_dialog_content = "Apa benda besar yang mendarat di luar sana di tempat terbuka? Raksasa Caelestit?!",
  ui_story_5003_50030101_46_dialog_content = "Anda tahu apa itu Colossus?!",
  ui_story_5003_50030101_47_dialog_content = "*Meraung*",
  ui_story_5003_50030101_48_dialog_content = "Mari kita singkirkan Eclipsites ini terlebih dahulu! Jangan biarkan mereka mencapai jalanan!",
  ui_story_5003_50030101_49_dialog_content = "Argh…",
  ui_story_5003_50030101_50_dialog_content = "Sangat jarang ada istirahat, pasti ada banyak kejutan akhir-akhir ini.",
  ui_story_5003_50030101_51_dialog_content = "Saya tidak tahu siapa Anda, tapi terima kasih atas bantuan Anda.",
  ui_story_5003_50030101_52_dialog_content = "Nama saya Vice, dan ini PlayerName dan Hiiro, komandan saya.",
  ui_story_5003_50030101_53_dialog_content = "Aku tahu.",
  ui_story_5003_50030101_54_dialog_content = "Hah?",
  ui_story_5003_50030101_55_dialog_content = "Sekarang saya telah membantu Anda, tidak akan terlalu banyak untuk meminta kompensasi, bukan?",
  ui_story_5003_50030101_56_dialog_content = "... Saya bertanggung jawab atas masalah ini. Silakan, sebutkan harga Anda.",
  ui_story_5003_50030101_57_dialog_content = "Aku tidak mencarimu. Anda di sana—murid dari Keluarga Sakae! Datang dan tunjukkan padaku apa yang kamu punya!",
  ui_story_5003_50030101_58_dialog_content = "Murid dari Keluarga Sakae... Siapa kamu?",
  ui_story_5003_50030101_59_dialog_content = "Tidak masalah siapa saya, yang penting Anda mengenali teknik saya.",
  ui_story_5003_50030101_60_dialog_content = "Teknik-teknik ini tidak dapat disangkal sama, tetapi saya tidak pernah berharap seorang murid Sakae kembali ke Cloud Mountain.",
  ui_story_5003_50030101_61_dialog_content = "Hah! Anda kembali juga, bukan?",
  ui_story_5003_50030101_62_dialog_content = "<color=#e8d9bb>*klang!*</color>",
  ui_story_5003_50030101_63_dialog_content = "Yah, itu mengecewakan... Kenapa kamu begitu lemah?",
  ui_story_5003_50030101_64_dialog_content = "...",
  ui_story_5003_50030101_65_dialog_content = "Apa yang Anda tahu? Komandan Hiiro sudah lama tidak beristirahat dengan baik! Jika dia punya, dia akan berada di atas angin!",
  ui_story_5003_50030101_66_dialog_content = "Vice, tolong... Jangan katakan lagi.",
  ui_story_5003_50030101_67_dialog_content = "Apa kekecewaan. Lain kali, kumpulkan dirimu. Jangan mempermalukan <color=#FFB400>Sakae Dojo</color>.",
  ui_story_5003_50030101_68_dialog_content = "Tunggu sebentar. Jika Anda seorang murid Keluarga Sakae, tahukah Anda bagaimana keadaan dojo akhir-akhir ini?",
  ui_story_5003_50030101_69_dialog_content = "Aku tahu apa yang kaucemaskan.",
  ui_story_5003_50030101_70_dialog_content = "Tidak apa-apa. Gunung Awan adalah <color=#FFB400>aman untuk kita</color> sekarang.",
  ui_story_5003_50030101_71_dialog_content = "Itu aman...?",
  ui_story_5003_50030101_72_dialog_content = "Hiiro, apakah kamu baik-baik saja? Pria aneh itu sudah pergi...",
  ui_story_5003_50030101_73_dialog_content = "Saya baik-baik saja. Kita ke dojo dulu. Bagaimanapun, itulah tujuan utama perjalanan kami.",
  ui_story_5003_50030101_74_dialog_content = "Tentang pria aneh itu barusan...",
  ui_story_5003_50030101_75_dialog_content = "Apakah kamu mengenalnya?",
  ui_story_5003_50030101_76_dialog_content = "Tidak, saya tidak mengenalnya, tapi saya yakin saya tahu gaya bertarungnya.",
  ui_story_5003_50030101_77_dialog_content = "Dia tampaknya terhubung dengan Keluarga Sakae. Aku percaya kita bisa bertemu lagi.",
  ui_story_5003_50030101_78_dialog_content = "Tentu.",
  ui_story_5003_50030101_79_dialog_content = "Lari, Hiiro! Cepat—ikuti aku!",
  ui_story_5003_50030101_80_dialog_content = "Master...?",
  ui_story_5003_50030101_81_dialog_content = "Mereka datang! Pindahkan! Keluar dari dojo!",
  ui_story_5003_50030101_82_dialog_content = "Sakae Dojo... Pasti ada di sini.",
  ui_story_5003_50030101_83_dialog_content = "Tapi kenapa ya...",
  ui_story_5003_50030101_84_dialog_content = "Selamat datang di Cwoud Bwossom Hotel!",
  ui_story_5003_50030101_85_dialog_content = "Kamu siapa? Apa yang terjadi di sini?",
  ui_story_5003_50030101_86_dialog_content = "Ah, tamu! Lebih lama lagi dan saya akan lupa bagaimana menerima tamu sekarang!",
  ui_story_5003_50030101_87_dialog_content = "Ah, di mana sopan santunku! Aku lupa memperkenalkan diri. Nama saya Tweety. Resepsionis fwedgling hotel!",
  ui_story_5003_50030101_88_dialog_content = "Maaf... Sepertinya aku tidak mengerti apa yang dia katakan.",
  ui_story_5003_50030101_89_dialog_content = "Masalah salju, aku hanya mendapat sedikit aksen. Silahkan masuk!",
  ui_story_5003_50030101_90_dialog_content = "Saya pikir dia berkata... Dia memiliki aksen?",
  ui_story_5003_50030101_91_dialog_content = "Hmm. Ini aksen lokal di sini di Cloud Mountain.",
  ui_story_5003_50030101_92_dialog_content = "Tweety, apakah ini hotel sumber air panas?",
  ui_story_5003_50030101_93_dialog_content = "Itu berat! Ini adalah pwace pecktacular untuk tinggal! Kami mendapat makanan, penginapan, dan sumber air panas. Kami bahkan menyediakan yukata!",
  ui_story_5003_50030101_94_dialog_content = "Hah? Apa yang dia katakan?",
  ui_story_5003_50030101_95_dialog_content = "Dia berkata, \"Penginapan dan pemandian air panas di sini sangat bagus. Kami juga menyediakan yukata.\"",
  ui_story_5003_50030101_96_dialog_content = "Terima kasih, wady bunga sakura! Saya akan mencoba untuk mengurangi aksen saya.",
  ui_story_5003_50030101_97_dialog_content = "Tapi itu terlalu kasar. Aku reawwy sowwy!",
  ui_story_5003_50030101_98_dialog_content = "Tidak, Anda tidak punya alasan untuk meminta maaf.",
  ui_story_5003_50030101_99_dialog_content = "Mendengar aksen akrab ini menenangkan saya.",
  ui_story_5003_50030101_100_dialog_content = "Keren? Hebat!",
  ui_story_5003_50030101_101_dialog_content = "Silakan menikmati masa tinggal Anda!",
  ui_story_5003_50030101_102_dialog_content = "Nikmati masa tinggal Anda...? Maaf, tapi kami di sini bukan untuk bersenang-senang, tapi untuk menyelidiki beberapa hal.",
  ui_story_5003_50030101_103_dialog_content = "Eh? Aku tahu tanda itu! Nona kenyal bwossom, apakah Anda dari Illumina? Sungguh pemandangan yang luar biasa bagi mata yang membumbung tinggi!",
  ui_story_5003_50030101_104_dialog_content = "Tunggu.. Maksudmu simbol ini? Anda tahu Illumina?",
  ui_story_5003_50030101_105_dialog_content = "Hah? Kapan dia mengatakan Illumina? Kenapa orang-orang di sini tahu tentang Illumina?",
  ui_story_5003_50030101_106_dialog_content = "Aku tahu Illumina!",
  ui_story_5003_50030101_108_dialog_content = "Pengucapan \"Illumina\" Anda sangat bagus. Jadi, Anda benar-benar tahu Illumina, ya?",
  ui_story_5003_50030101_109_dialog_content = "Apakah Illumina terkenal di sini di Cloud Mountain?",
  ui_story_5003_50030101_110_dialog_content = "Tidak keren. Saya hanya tahu karena saya dulu bekerja di sana. Kagum Anda fwom di sana juga?",
  ui_story_5003_50030101_111_dialog_content = "Hah? Demikian juga?",
  ui_story_5003_50030101_112_dialog_content = "Mengapa Anda wook begitu terkejut? Saya juga anggota Couwier Union!",
  ui_story_5003_50030101_113_dialog_content = "Anda berasal dari <color=#FFB400>Serikat Kurir</color>?",
  ui_story_5003_50030101_X113_dialog_content = "Ya!",
  ui_story_5003_50030101_114_dialog_content = "Serikat Kurir? Ya, kami terlalu mengenalnya.",
  ui_story_5003_50030101_X114_dialog_content = "Dan lihat, anak itu memang memiliki ekor burung!!",
  ui_story_5003_50030101_115_dialog_content = "Kicauan! Kenapa kamu tiba-tiba bertingkah gila?",
  ui_story_5003_50030101_116_dialog_content = "Erm, maaf... PlayerName mencari sesuatu yang \"eksotis\" selama perjalanan ini.",
  ui_story_5003_50030101_117_dialog_content = "PlayerName menjadi sedikit bersemangat karena semuanya tampak terlalu \"akrab\".",
  ui_story_5003_50030101_118_dialog_content = "Aku mengerti! Anda kagum teman dari Couwier Union? Betapa indahnya!",
  ui_story_5003_50030101_119_dialog_content = "Maaf, saya akan mencoba untuk tenang, tapi Hiiro... Apa yang akan kita lakukan sekarang?",
  ui_story_5003_50030101_120_dialog_content = "Saya kira kita bisa mempercayai anggota Serikat Kurir.",
  ui_story_5003_50030101_121_dialog_content = "Mari kita tinggal sebentar dulu dan lihat apa yang sebenarnya terjadi di sini.",
  ui_story_5003_50030101_122_dialog_content = "Saya perlu tahu... Mengapa tempat ini sekarang menjadi hotel?",
  ui_story_5003_50030201_1_dialog_content = "Apakah Anda akan berada di hotel untuk makan malam nanti, Sanki?",
  ui_story_5003_50030201_2_dialog_content = "Saya punya beberapa bahan bagus untuk Anda hari ini.",
  ui_story_5003_50030201_3_dialog_content = "Tidak... Ada tamu di hotel. Anda harus kembali sekarang.",
  ui_story_5003_50030201_4_dialog_content = "Eh? Meninggalkan sudah?",
  ui_story_5003_50030201_5_dialog_content = "Ah... Anak ini. Masih sangat dingin bahkan setelah sekian hari kita bersama.",
  ui_story_5003_50030201_6_dialog_content = "Saatnya yukata!",
  ui_story_5003_50030201_7_dialog_content = "Oh! Jadi, inilah yukata yang Hiiro bicarakan!",
  ui_story_5003_50030201_8_dialog_content = "Kalian semua terlihat sangat cantik dengan yukata itu!",
  ui_story_5003_50030201_9_dialog_content = "Terima kasih! Tapi, Tweety, jika Anda adalah anggota Serikat Kurir, apa yang Anda lakukan bekerja di Cloud Mountain?",
  ui_story_5003_50030201_10_dialog_content = "Orang tua saya bekerja di benua itu ketika saya masih kecil, dan tetangga kami Gwammy merawat saya!",
  ui_story_5003_50030201_11_dialog_content = "Saya sedang tidak bekerja. Gwammy mentweet saya seperti gw dan anak perempuannya sendiri, jadi saya datang dan membantu di hotel saat istirahat!",
  ui_story_5003_50030201_12_dialog_content = "Aku tahu.",
  ui_story_5003_50030201_13_option_content = [[
Saya minta maaf... 
aku jadi bingung lagi.]],
  ui_story_5003_50030201_14_dialog_content = "Ini membuatku sakit kepala.",
  ui_story_5003_50030201_15_option_content = [[
Vice, apakah kamu terbiasa dengan aksennya
sudah?]],
  ui_story_5003_50030201_16_dialog_content = "Haha, saya pikir saya cukup bisa memahaminya sekarang!",
  ui_story_5003_50030201_17_dialog_content = "Dia berkata, \"Nenek memperlakukan saya seperti seorang cucu, jadi tentu saja saya harus kembali dan membantunya dengan hotel ketika saya sedang berlibur.\"",
  ui_story_5003_50030201_18_dialog_content = "Aku pulang.",
  ui_story_5003_50030201_19_dialog_content = "Selamat datang di hotel kami. Maaf, harus keluar sekarang, jadi saya tidak bisa menyapa Anda.",
  ui_story_5003_50030201_20_dialog_content = "Gwammy ada di chawge hotel ini!",
  ui_story_5003_50030201_21_dialog_content = "Permisi bu, apakah anda dari Astra daratan juga?",
  ui_story_5003_50030201_22_dialog_content = "Tidak, saya lahir dan besar di sini di Cloud Mountain.",
  ui_story_5003_50030201_23_dialog_content = "Apakah Anda tahu siapa kita?",
  ui_story_5003_50030201_24_dialog_content = "Ini pertama kalinya kita bertemu.",
  ui_story_5003_50030201_25_dialog_content = "Besar! Sepertinya Anda orang lokal meskipun Anda orang Universe yang fasih!",
  ui_story_5003_50030201_26_dialog_content = "Haha, kamu lucu.",
  ui_story_5003_50030201_27_dialog_content = "Maaf, ini adalah pertama kalinya kami di sini. Kami tidak terlalu akrab dengan tempat ini, jadi kami mungkin telah mengajukan terlalu banyak pertanyaan.",
  ui_story_5003_50030201_28_dialog_content = "Tidak perlu bersikap sopan. Anda adalah tamu di Cloud Blossom Hotel, jadi jangan ragu untuk menanyakan apa pun kepada saya.",
  ui_story_5003_50030201_29_dialog_content = "Bolehkah kami menanyakan sesuatu tentang Sakae Dojo?",
  ui_story_5003_50030201_30_dialog_content = "Dojo Sakae? Hanya siapa kamu?",
  ui_story_5003_50030201_31_dialog_content = "Tidak masalah siapa saya. Saya baru saja mendengar bahwa tempat ini awalnya adalah sebuah dojo... dan saya menjadi sedikit penasaran.",
  ui_story_5003_50030201_32_dialog_content = "Maaf, tamu terkasih, meskipun saya menjalankan hotel ...",
  ui_story_5003_50030201_33_dialog_content = "Saya sebenarnya bukan pemiliknya, dan saya tidak tahu banyak tentang dojo itu.",
  ui_story_5003_50030201_34_dialog_content = "Ketika saya datang ke sini, dojo sudah menghilang, hanya menyisakan sepetak tanah terbuka.",
  ui_story_5003_50030201_35_dialog_content = "Tamu yang saya hormati, bolehkah saya mengetahui nama Anda?",
  ui_story_5003_50030201_36_dialog_content = "Saya bisa bertanya-tanya tentang Anda. Jika ada sesuatu yang muncul, saya akan memberi tahu Anda.",
  ui_story_5003_50030201_37_dialog_content = "Baik. Nama saya Hiiro.",
  ui_story_5003_50030201_38_dialog_content = "Hiiro... Nama yang bagus.",
  ui_story_5003_50030201_39_dialog_content = "Tweety, sudahkah Anda memeriksa tamu kami dan bertanya berapa lama mereka berencana untuk menginap?",
  ui_story_5003_50030201_40_dialog_content = "Semua check in selama tiga hari!",
  ui_story_5003_50030201_41_dialog_content = "Baik. Mari berharap tamu kami dapat tetap low profile selama tiga hari ke depan...",
  ui_story_5003_50030201_42_dialog_content = "Saya jamin, kami <color=#FFB400>tidak akan mengganggu siapa pun yang tidak terkait dengan masalah ini</color>.",
  ui_story_5003_50030201_43_dialog_content = "Selain itu, harap tetap diam tentang keberadaan kami di sini.",
  ui_story_5003_50030201_44_dialog_content = "Tentu saja, kami tidak pernah mengungkapkan informasi tamu kami kepada siapa pun. Harap yakinlah.",
  ui_story_5003_50030201_45_dialog_content = "Anda juga bisa pergi ke Spa Street dan bertanya-tanya di sana. Mungkin Anda akan menemukan informasi yang Anda cari.",
  ui_story_5003_50030201_46_dialog_content = "Kami berjalan di sekitar jalan sepanjang hari tetapi tidak menemukan apa pun. . .",
  ui_story_5003_50030201_47_dialog_content = "Komandan Hiiro, haruskah kita kembali dan istirahat dulu sebelum melanjutkan?",
  ui_story_5003_50030201_48_dialog_content = "Kalau tidak, mungkin ada situasi lain seperti pagi ini...",
  ui_story_5003_50030201_49_dialog_content = "Apakah Anda khawatir jika saya menghadapi tantangan lain dalam kondisi saya saat ini, saya mungkin kalah lagi?",
  ui_story_5003_50030201_50_dialog_content = "Maaf.",
  ui_story_5003_50030201_51_dialog_content = "Tidak, tidak... Tidak perlu meminta maaf. Anda benar untuk khawatir. Mari kita kembali dan beristirahat dengan baik hari ini.",
  ui_story_5003_50030201_52_dialog_content = "Itu adalah \"mata air panas\" untuk Anda. Tampaknya memiliki sifat peremajaan.",
  ui_story_5003_50030201_53_dialog_content = "Bukankah suhunya berbeda dari yang dikatakan Vice sebelumnya? aku merasa sedikit pusing...",
  ui_story_5003_50030201_54_dialog_content = "Bukankah kamu baru saja tiba di musim semi?",
  ui_story_5003_50030201_55_dialog_content = "Yeah... Aku selalu mandi dengan sangat cepat.",
  ui_story_5003_50030201_56_dialog_content = "Tunggu! Bukankah kamu yang dulu? Orang yang tiba-tiba memulai <color=#FFB400>duel dengan Hiiro</color>!",
  ui_story_5003_50030201_57_dialog_content = "Apakah yang Anda maksud: yang berambut pink",
  ui_story_5003_50030201_58_dialog_content = "Apa yang kamu lakukan di sini? Apa yang kamu inginkan?",
  ui_story_5003_50030201_59_dialog_content = "Ini disebut <color=#FFB400>\"perdebatan\"</color>, bukan \"duel\". Apakah Anda benar-benar perlu takut padaku?",
  ui_story_5003_50030201_60_dialog_content = "Saya tidak sering bertemu dengan sesama murid. Wajar jika kita harus berdebat... dan bukankah Hiiro juga menyetujuinya?",
  ui_story_5003_50030201_61_dialog_content = "Hah? Saya rasa itu... masuk akal?",
  ui_story_5003_50030201_62_dialog_content = "Vice, jangan main-main dengan yukata.",
  ui_story_5003_50030201_63_dialog_content = "Anda harus santai sesekali, Komandan Hiiro! Jangan terlalu tegang!",
  ui_story_5003_50030201_64_dialog_content = "Apakah itu... suara-suara yang datang dari kamar mandi wanita? Sepertinya tempat ini tidak terlalu kedap suara...",
  ui_story_5003_50030201_65_dialog_content = "Sama sekali tak tahu…",
  ui_story_5003_50030201_66_dialog_content = "Kalau begitu mari kita bicara di tempat lain.",
  ui_story_5003_50030201_67_dialog_content = "Omong-omong, Komandan Hiiro seperti bunga sakura.",
  ui_story_5003_50030201_68_dialog_content = "Saya setuju! Hiiwo seperti yang Anda katakan!",
  ui_story_5003_50030201_69_dialog_content = "Mungkin karena saya anggota <color=#FFB400>Keluarga Sakura</color>.",
  ui_story_5003_50030201_70_dialog_content = "Keluarga Sakuwa? Aku mendengarnya dari Gwammy. Yang itu <color=#FFB400>misterius dan kuat</color> keluarga.",
  ui_story_5003_50030201_71_dialog_content = "Tapi Sakuwa adalah... Bukankah mereka menghilang beberapa waktu yang lalu?",
  ui_story_5003_50030201_72_dialog_content = "Memang. Mereka sudah lama menghilang... Waktu keluarga Sakura singkat, tapi mereka menghadapi kematian dengan keberanian yang tak tergoyahkan.",
  ui_story_5003_50030201_73_dialog_content = "Saya sudah menjadi yang terakhir dari barisan saya jauh sebelum saya dewasa.",
  ui_story_5003_50030201_74_dialog_content = "Astaga... Aku tidak bermaksud membuat cerita sedih seperti itu...",
  ui_story_5003_50030201_75_dialog_content = "Jangan khawatir. Itu bukan kenangan yang sangat menyedihkan bagi saya.",
  ui_story_5003_50030201_76_dialog_content = "Saya dibesarkan oleh tuan saya, jadi saya ingat banyak tentang Keluarga Sakura.",
  ui_story_5003_50030201_77_dialog_content = "Tuanku adalah hal yang paling dekat dengan keluarga bagiku... Jadi aku tidak terlalu peduli dengan keluarga kandungku.",
  ui_story_5003_50030201_78_dialog_content = "Selain itu, bisa kembali ke kampung halamanku seperti ini dan melihat bunga sakura di sini sudah cukup baik bagiku.",
  ui_story_5003_50030201_79_dialog_content = "Maaf, saya pikir Anda mengikuti kami ke hotel.",
  ui_story_5003_50030201_80_dialog_content = "Tapi kalau dipikir-pikir, kamu memakai yukata... Jadi kamu pasti tamu di sini.",
  ui_story_5003_50030201_81_dialog_content = "Ya. Tapi lebih tepatnya, saya seorang investor di hotel ini. Ini kartu nama saya.",
  ui_story_5003_50030201_82_dialog_content = "Anda salah satu investor hotel? Tapi kartu nama Anda mengatakan Anda bekerja di Umbraton!?",
  ui_story_5003_50030201_83_dialog_content = "Kalian bisa memanggilku Taki. Saya memiliki perusahaan di Umbraton. Anda dapat datang dan menemukan saya jika Anda memiliki bisnis di sana di masa depan.",
  ui_story_5003_50030201_84_dialog_content = "Saya cukup terkejut mengetahui Tweety's dari Courier Union, dan sekarang Anda dari Astra.",
  ui_story_5003_50030201_X84_dialog_content = "Tapi sekarang saya tiba-tiba merasa bahwa bertemu orang-orang dari suatu tempat yang akrab sebenarnya cukup menghibur.",
  ui_story_5003_50030201_85_dialog_content = "Saya PlayerName. Saya senang bertemu Anda seperti ini, karena saya yakin Anda akan membuat penyelidikan kami di sini jauh lebih mudah.",
  ui_story_5003_50030201_86_dialog_content = "Hmm, itu ide yang menarik. Saya mungkin hanya menahan Anda untuk itu dan meminta Anda untuk membayar.",
  ui_story_5003_50030201_87_dialog_content = "Apakah itu termasuk konsultasi juga?",
  ui_story_5003_50030201_88_dialog_content = "Sekarang, sekarang, itu sudah cukup. Hiiro dan saya sama-sama dari Sakae Dojo, Anda tahu itu, kan?",
  ui_story_5003_50030201_89_dialog_content = "Aku tahu... Hiiro memberitahu kami sesuatu tentang dojo.",
  ui_story_5003_50030201_90_dialog_content = "Hmm, sepertinya kalian adalah orang yang bisa kupercaya.",
  ui_story_5003_50030201_91_dialog_content = "<anim type=Shake><color=#e8d9bb>*Suara mendesing*-</color></anim>",
  ui_story_5003_50030201_92_dialog_content = "Hei, apakah seseorang baru saja berlari keluar?",
  ui_story_5003_50030201_93_dialog_content = "Hah? Siapa itu?",
  ui_story_5003_50030201_94_dialog_content = "Aku tidak tahu. Saya tidak mengenali mereka.",
  ui_story_5003_50030201_95_dialog_content = "Oke, aku akan lihat!",
  ui_story_5003_50030201_96_dialog_content = "<size=30>Hah? Maksudmu seseorang hanya...</size>",
  ui_story_5003_50030201_97_dialog_content = "(Vice dan yang lainnya sepertinya sedang membicarakan sesuatu di pemandian wanita.)",
  ui_story_5003_50030201_98_dialog_content = "<size=30>Sst! Apa suara di luar? Tweety, jangan pergi ke sana dulu. Ayo pergi...</size>",
  ui_story_5003_50030201_99_dialog_content = "Vice, apakah kalian baik-baik saja di sana?",
  ui_story_5003_50030201_100_dialog_content = "PlayerName? Anda...",
  ui_story_5003_50030201_101_dialog_content = "Saya baru saja masuk dari luar untuk melihat apakah ada yang salah.",
  ui_story_5003_50030201_102_dialog_content = "Mencoba mengintip? Saya tidak akan pernah berharap ...",
  ui_story_5003_50030201_103_dialog_content = "Hah? Ada apa?",
  ui_story_5003_50030201_104_dialog_content = "Eh-eh-eh? Apakah Anda ingin mengintip?",
  ui_story_5003_50030201_105_dialog_content = "Mengintip? Tidak, bukan itu sama sekali! Saya tidak melihat ke dalam!",
  ui_story_5003_50030201_106_dialog_content = "Saya baru saja melihat orang yang mencurigakan berlari keluar, jadi saya masuk untuk melihat apa yang terjadi.",
  ui_story_5003_50030201_107_dialog_content = "Hanya saja tempat ini tidak terlalu kedap suara. Saya tidak sengaja mendengar ...",
  ui_story_5003_50030201_108_dialog_content = "Apa yang kamu dengar?",
  ui_story_5003_50030201_109_dialog_content = "Pertama, saya mendengar, \"Jangan bermain-main dengan yukata.\" Tidak, aku benar-benar tidak menguping!",
  ui_story_5003_50030201_110_dialog_content = "PlayerName! Beritahu kami yang sebenarnya!",
  ui_story_5003_50030201_111_dialog_content = "Tunggu! Keburukan! Aku benar-benar tidak mengintip!",
  ui_story_5003_50030201_112_dialog_content = "Jadi, siapa yang mengintip dari luar?",
  ui_story_5003_50030201_113_dialog_content = "Saya pikir ... itu anak-anak?",
  ui_story_5003_50030201_114_dialog_content = "Maksudmu anak sepertimu!?",
  ui_story_5003_50030201_115_dialog_content = "Tidak! Saya pikir orang yang keluar dari hotel itu sebenarnya mengintip!",
  ui_story_5003_50030201_116_dialog_content = "Saya ingat melihat seorang anak laki-laki bertelanjang dada dengan rambut panjang... Mungkin dia dari Spa Street!",
  ui_story_5003_50030201_117_dialog_content = "Kami bahkan tidak memiliki gadis dengan rambut panjang di sini...",
  ui_story_5003_50030201_118_dialog_content = "PlayerName, Anda tidak berbohong kepada saya, kan?",
  ui_story_5003_50030201_119_dialog_content = "Tentu saja tidak!",
  ui_story_5003_50030201_X119_dialog_content = "Tunggu saja. Aku yakin aku bisa mengenalinya jika aku melihatnya lagi. Ayo kita hadapi dia bersama!",
  ui_story_5003_50030301_1_dialog_content = "Guru, mengapa orang-orang berbalik melawan dojo?",
  ui_story_5003_50030301_2_dialog_content = "Ketika kita menghadapi krisis, kita semua melakukan apa yang kita bisa untuk bertahan hidup.",
  ui_story_5003_50030301_3_dialog_content = "Jika keinginan untuk bertahan hidup terkonsentrasi pada satu hal tertentu, hal itu dapat menyebabkan konflik.",
  ui_story_5003_50030301_4_dialog_content = "Kami melarikan diri untuk menjauh dari konflik berbahaya itu.",
  ui_story_5003_50030301_5_dialog_content = "Tapi Anda selalu mengajari saya untuk tidak pernah takut mati dan berjuang dengan berani sampai akhir ... Tapi, Guru ... kami melarikan diri?",
  ui_story_5003_50030301_6_dialog_content = "Melarikan diri tidak selalu merupakan tindakan pengecut dan juga bukan merupakan pengabaian tanggung jawab seseorang. Alasan saya melakukan apa yang saya lakukan ...",
  ui_story_5003_50030301_7_dialog_content = "Itu karena aku punya sesuatu yang lebih penting untuk dilindungi. Saya harus menjaga <color=#FFB400>kunci</color> aman, Hiiro.",
  ui_story_5003_50030301_8_dialog_content = "Kapan kita akan kembali? Kapan konflik berakhir?",
  ui_story_5003_50030301_9_dialog_content = "Hiiro, kami tidak akan kembali...",
  ui_story_5003_50030301_10_dialog_content = "Komandan Hiiro, apakah Anda baik-baik saja? Susah tidur nyenyak lagi?",
  ui_story_5003_50030301_11_dialog_content = "Tidak, aku baik-baik saja. Aku hanya sedang memikirkan sesuatu.",
  ui_story_5003_50030301_12_dialog_content = "Anda semua bangun pagi-pagi sekali! Maaf, aku belum sempat menyiapkan sarapan untukmu.",
  ui_story_5003_50030301_13_dialog_content = "Maaf, Bu. Kami berencana untuk berangkat lebih awal dan tidak berencana mengganggu Anda.",
  ui_story_5003_50030301_14_dialog_content = "Tolong, jangan katakan itu. Ini semua adalah bagian dari layanan di sini.",
  ui_story_5003_50030301_15_dialog_content = "Jangan khawatir tentang kami. Ada sesuatu yang harus kita selidiki di jalanan.",
  ui_story_5003_50030301_16_dialog_content = "Jadi... Apakah Anda ingin sarapan ketika Anda kembali? Tweety dan saya pergi ke pasar untuk membeli beberapa bahan yang bagus.",
  ui_story_5003_50030301_17_dialog_content = "Anda terlalu baik. Tapi kita makan di luar saja.",
  ui_story_5003_50030301_18_dialog_content = "Baiklah, baiklah.",
  ui_story_5003_50030301_19_dialog_content = "PlayerName, mari kita mulai penyelidikan kita dengan hotel.",
  ui_story_5003_50030301_20_dialog_content = "Sebenarnya, kami memanfaatkan waktu kami di pemandian air panas kemarin untuk bertanya kepada Tweety tentang hotel.",
  ui_story_5003_50030301_21_dialog_content = "Kami tidak mempelajari sesuatu yang mencurigakan. Meskipun nenek mengelola hotel, dia bukan pemiliknya.",
  ui_story_5003_50030301_22_dialog_content = "Secara umum, tidak ada yang aneh dengan membeli tanah untuk membangun bisnis baru.",
  ui_story_5003_50030301_23_dialog_content = "Namun, ada yang istimewa dari tanah tempat dojo ini dibangun.",
  ui_story_5003_50030301_24_dialog_content = "Di Timur Jauh, kami menyebut tempat seperti ini \"tanah tidak suci\".",
  ui_story_5003_50030301_25_dialog_content = "Anda lihat, orang cenderung menjauhi tempat-tempat di mana insiden mengerikan telah terjadi.",
  ui_story_5003_50030301_26_dialog_content = "Jauhi mereka? Hotel ini sepertinya tidak memiliki tamu lain.",
  ui_story_5003_50030301_27_dialog_content = "Keluarga Sakae hampir musnah dalam semalam. Api membakar dojo, hanya menyisakan reruntuhan di tempatnya.",
  ui_story_5003_50030301_28_dialog_content = "Siapa yang mau membeli tanah berlumuran darah dan membangun hotel sumber air panas tanpa pelanggan?",
  ui_story_5003_50030301_29_dialog_content = "Kita harus menemukan investornya. Nenek memberi tahu kami bahwa dia dapat ditemukan di Spa Street.",
  ui_story_5003_50030301_30_dialog_content = "Namanya adalah...",
  ui_story_5003_50030301_31_option_content = "Taki! Saya tahu dia!",
  ui_story_5003_50030301_32_dialog_content = "PlayerName, bagaimana Anda tahu nama investor?",
  ui_story_5003_50030301_33_dialog_content = "Dia bilang dia investor kemarin! Hiiro, dia yang \"berdebat\" denganmu! Dojo-mate lamamu!",
  ui_story_5003_50030301_34_dialog_content = "Orang itu?",
  ui_story_5003_50030301_35_dialog_content = "Dimana kamu kemarin? Bagaimana Anda bertemu dengannya?",
  ui_story_5003_50030301_36_dialog_content = "Aku bertemu dengannya di hotel. Saya menyapa, dan kami akhirnya mengobrol.",
  ui_story_5003_50030301_37_dialog_content = "Apakah Anda tidak bertanya kepadanya tentang hotel?",
  ui_story_5003_50030301_38_dialog_content = "Tidak juga... Percakapan kami terputus ketika saya melihat seseorang berlari keluar hotel.",
  ui_story_5003_50030301_39_dialog_content = "Maaf, saya benar-benar mengira Anda mengintip kami ketika Anda berdiri di luar pemandian wanita kemarin.",
  ui_story_5003_50030301_40_dialog_content = "Yah, tentu saja tidak! Saya hanya khawatir jika sesuatu terjadi, Anda akan tertangkap basah...",
  ui_story_5003_50030301_41_dialog_content = "Jadi saya memutuskan untuk masuk dulu dan melihat apa yang terjadi.",
  ui_story_5003_50030301_42_dialog_content = "Eh? Benarkah twue yang kamu intip kemarin??",
  ui_story_5003_50030301_43_dialog_content = "Tidak, aku hanya mendengarkan... Maksudku, tidak! Saya tidak melihat apa-apa!",
  ui_story_5003_50030301_44_dialog_content = "Tweety, apa yang kamu lakukan di sini?",
  ui_story_5003_50030301_45_dialog_content = "Giliran saya untuk mendapatkan gwoceries!",
  ui_story_5003_50030301_46_dialog_content = "Jadi Tweety juga bertanggung jawab atas belanja bahan makanan.",
  ui_story_5003_50030301_47_dialog_content = "Tweety, kamu kenal Taki?",
  ui_story_5003_50030301_48_dialog_content = "Aku tahu Taki! Saya bisa merayu dia jika Anda membutuhkan saya!",
  ui_story_5003_50030301_49_dialog_content = "Baiklah, kami mengandalkan Anda untuk membantu kami menemukannya.",
  ui_story_5003_50030301_50_dialog_content = "Jadi, kami sudah di jalan sepanjang hari dan tidak menemukan apa-apa lagi, seperti kemarin...",
  ui_story_5003_50030301_51_dialog_content = "Betapa anehnya... Saya tidak dapat menemukan Tuan Taki hari ini... Apakah Tuan menghilang dalam kepulan asap?",
  ui_story_5003_50030301_52_dialog_content = "Taki terluka di Spa Street beberapa hari terakhir... Mungkin dia pergi ke tempat lain hari ini?",
  ui_story_5003_50030301_53_dialog_content = "dia adalah <color=#FFB400>berkeliaran di Jalan Spa</color>? Apa yang dia lakukan?",
  ui_story_5003_50030301_54_dialog_content = "Pak Taki mengatakan sudah lama sejak dia kembali jadi dia ingin bersenang-senang dan akan kembali terlambat.",
  ui_story_5003_50030301_55_dialog_content = "Wook pada saat itu... Bagaimana kalau semua orang kembali dan istirahat dulu?",
  ui_story_5003_50030301_56_dialog_content = "Saya akan memberikan kicauan ketika Tuan Taki kembali.",
  ui_story_5003_50030301_57_dialog_content = "Jika dia mendengar bahwa kita ingin bertemu dengannya... Dia mungkin akan mencurigai sesuatu dan menghindari bertemu dengan kita.",
  ui_story_5003_50030301_58_option_content = "Saya pikir Anda benar.",
  ui_story_5003_50030301_59_dialog_content = "Ketika kami bertemu kemarin, dia sedikit terkejut dan bertanya, \"Bukankah kamu baru saja tiba di mata air?\"",
  ui_story_5003_50030301_60_option_content = "Kurasa tidak.",
  ui_story_5003_50030301_61_dialog_content = "Ketika saya melihat Taki kemarin, dia terlihat sangat tenang ketika berbicara tentang dojo.",
  ui_story_5003_50030301_62_dialog_content = "Saya tidak berpikir dia punya sesuatu untuk disembunyikan.",
  ui_story_5003_50030301_63_dialog_content = "Nah, mungkin Pak Taki sudah kembali ke hotel?",
  ui_story_5003_50030301_64_dialog_content = "Mungkin kita tidak melihatnya di jalan karena kita hanya merindukannya...?",
  ui_story_5003_50030301_65_dialog_content = "Dua, dua!",
  ui_story_5003_50030301_66_dialog_content = "Jadi, ketika Taki kembali ke hotel, Anda akan memberi tahu kami hal pertama, kan, Tweety?",
  ui_story_5003_50030301_67_dialog_content = "Tentu saja! Anda bisa memelintir saya!",
  ui_story_5003_50030301_68_dialog_content = "Baiklah, mari kita kembali ke hotel, kalau begitu.",
  ui_story_5003_50030301_69_dialog_content = "PlayerName, bisakah saya meminta Anda untuk mengawasi sesuatu yang aneh?",
  ui_story_5003_50030301_70_dialog_content = "Ada yang aneh?",
  ui_story_5003_50030301_71_dialog_content = "Betul sekali. Saya percaya kemampuan psikis Anda mungkin berguna di sini.",
  ui_story_5003_50030301_72_dialog_content = "Oke. Saya mengerti.",
  ui_story_5003_50030301_73_dialog_content = "Gan... Graaah...",
  ui_story_5003_50030301_74_dialog_content = "Erm... Kurasa aku baru saja mendengar sesuatu yang aneh datang dari...",
  ui_story_5003_50030301_75_dialog_content = "*Meraung*",
  ui_story_5003_50030301_76_dialog_content = "Ahhh! Ecwipsite!",
  ui_story_5003_50030301_77_dialog_content = "*Meraung*",
  ui_story_5003_50030301_78_dialog_content = "Bagaimana? Apa yang membuat para Ecwipsite ini kagum di Spa Street?",
  ui_story_5003_50030301_79_dialog_content = "Oh tidak! Ada terlalu banyak dari mereka!",
  ui_story_5003_50030301_80_dialog_content = "Ecwipsite ini tidak terlalu tangguh! Aku bisa!",
  ui_story_5003_50030301_81_dialog_content = "Mundur! Pergi ke hotel! Jalannya sempit di sini! Blokir!",
  ui_story_5003_50030301_82_dialog_content = "PlayerName, pergi dan beri tahu Nenek. Kami akan mengurus Eclipsites di luar!",
  ui_story_5003_50030301_83_dialog_content = "Baiklah!",
  ui_story_5003_50030301_84_dialog_content = "*Meraung*",
  ui_story_5003_50030301_85_dialog_content = "Oh tidak! Komandan Hiiro! Eclipsites sedang menuju ke jalan!",
  ui_story_5003_50030301_86_dialog_content = "Aku akan menghentikan mereka!",
  ui_story_5003_50030301_87_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_88_dialog_content = "Siapa yang bersembunyi di sana? Tunjukan dirimu!",
  ui_story_5003_50030301_89_dialog_content = "Kita bertemu lagi, Hiiro.",
  ui_story_5003_50030301_90_dialog_content = "Bu! Bu, di mana Anda? Bu!?",
  ui_story_5003_50030301_91_dialog_content = "Aneh... Tidak ada orang di hotel?",
  ui_story_5003_50030301_92_dialog_content = "Tunggu...",
  ui_story_5003_50030301_X92_dialog_content = "Siapa yang bersembunyi di halaman? Tunjukan dirimu!",
  ui_story_5003_50030301_93_dialog_content = "Kau...",
  ui_story_5003_50030301_94_dialog_content = "...",
  ui_story_5003_50030301_95_dialog_content = "Kau orang yang berlari keluar tadi malam, bukan?",
  ui_story_5003_50030301_96_dialog_content = "Gaah... Graaah...",
  ui_story_5003_50030301_97_dialog_content = "The Eclipsites hampir dikalahkan. Apa yang ingin Anda bicarakan dengan saya? Silakan dan katakan.",
  ui_story_5003_50030301_98_dialog_content = "Taki, mengapa Anda membangun hotel di atas Sakae Dojo?",
  ui_story_5003_50030301_99_dialog_content = "Satu-satunya alasan yang dapat saya pikirkan adalah bahwa Anda ingin menyembunyikan sesuatu.",
  ui_story_5003_50030301_100_dialog_content = "Sakae Dojo tidak ada lagi. Tanahnya tersedia, jadi tentu saja, saya membelinya.",
  ui_story_5003_50030301_101_dialog_content = "Apa kaubilang!?",
  ui_story_5003_50030301_102_dialog_content = "Tenang. Jika Anda akan membiarkan emosi menguasai diri Anda, saya menyarankan Anda untuk melupakan pertanyaan ini.",
  ui_story_5003_50030301_103_dialog_content = "Keluarga Sakae dibantai olehnya <color=#FFB400>musuh</color>. Guru tidak punya pilihan selain melarikan diri dengan saya, dan Anda ingin saya tenang?",
  ui_story_5003_50030301_104_dialog_content = "<size=45>Aku di sini untuk membalas dendam!</size>",
  ui_story_5003_50030301_105_dialog_content = "Anda bahkan tidak bisa membedakan teman dari musuh sekarang. Saya sudah bilang, saya sesama murid Anda.",
  ui_story_5003_50030301_106_dialog_content = "Lihat bekas luka ini di wajahku? Ini ditinggalkan oleh tuanmu, kepala Sakae Dojo, <color=#FFB400>Sakae Shigeo</color>.",
  ui_story_5003_50030301_107_dialog_content = "Tuanku? Tapi kenapa?",
  ui_story_5003_50030301_108_dialog_content = "Sakae Shigeo berpikir aku terlalu kurus dan lemah. Sorot matanya memberitahuku bahwa dia tidak akan menerimaku sebagai murid.",
  ui_story_5003_50030301_109_dialog_content = "Jadi saya menyerangnya... dan dia memotong saya, tapi dia juga mengakui bahwa saya punya potensi.",
  ui_story_5003_50030301_110_dialog_content = "Jadi dia menerimamu sebagai murid Sakae Dojo?",
  ui_story_5003_50030301_111_dialog_content = "Benar. Aku bersumpah pada Sakae Shigeo bahwa jika aku tidak bisa mengalahkannya dalam waktu tiga tahun, aku akan pergi atas kemauanku sendiri.",
  ui_story_5003_50030301_112_dialog_content = "Dan bahwa saya tidak akan memberi tahu siapa pun bahwa saya adalah murid dari klan Sakae agar tidak mempermalukan Sakae.",
  ui_story_5003_50030301_113_dialog_content = "Apakah Anda menang pada akhirnya?",
  ui_story_5003_50030301_114_dialog_content = "Tidak, dia membiarkan saya menang ... Pada akhirnya, saya meninggalkan Cloud Mountain dan pergi ke daratan.",
  ui_story_5003_50030301_115_dialog_content = "Saya belum memberi tahu siapa pun bahwa saya adalah murid dari klan Sakae, jadi saya tidak suka dicurigai tanpa alasan.",
  ui_story_5003_50030301_116_dialog_content = "Kaulah yang menyerangku lebih dulu. Aku hanya mencurigaimu karena aku tidak tahu yang sebenarnya.",
  ui_story_5003_50030301_117_dialog_content = "Kami hanya sparring. Aku tidak mencoba menyakitimu. Bahkan jika Anda tidak mengenal saya, Anda harus tahu gaya Sakae.",
  ui_story_5003_50030301_118_dialog_content = "Saya tidak mendapatkan berita sampai setelah Sakae Dojo jatuh.",
  ui_story_5003_50030301_119_dialog_content = "Jadi yang bisa saya lakukan hanyalah membeli tanah tempat dojo itu berdiri agar tidak jatuh ke tangan orang lain.",
  ui_story_5003_50030301_120_dialog_content = "Saat pertama kali kita bertemu, kamu bilang <color=#FFB400>\"Gunung Cloud aman sekarang.\"</color> Apa yang kamu maksud dengan itu?",
  ui_story_5003_50030301_121_dialog_content = "Saya melakukan beberapa penyelidikan. Para penyerang dojo sudah pergi.",
  ui_story_5003_50030301_122_dialog_content = "Apa yang terjadi pada mereka?",
  ui_story_5003_50030301_123_dialog_content = "Mereka dibunuh. Atau mungkin para murid Sakae Dojo bertempur dengan gagah berani, dan tewas dalam pertempuran.",
  ui_story_5003_50030301_124_dialog_content = "Hancur bersama dalam pertempuran? Jadi, maksudmu... Musuhku sudah dikalahkan sebelum aku kembali?",
  ui_story_5003_50030301_125_dialog_content = "Benar. Semuanya sudah berakhir.",
  ui_story_5003_50030301_126_dialog_content = "Bagaimanapun, kami dari dojo yang sama. Saya mengatakan ini karena saya tidak ingin melihat Anda diperbudak oleh masa lalu.",
  ui_story_5003_50030301_127_dialog_content = "...",
  ui_story_5003_50030301_128_dialog_content = "Nenek datang kepada saya dan mengatakan bahwa dia ingin membangun sebuah hotel.",
  ui_story_5003_50030301_129_dialog_content = "Maksudmu... Bukan kamu yang ingin membangun hotel di tanah ini? Itu dia?",
  ui_story_5003_50030301_130_dialog_content = "Apa yang dia coba sembunyikan dengan membangun hotel di atas reruntuhan dojo?",
  ui_story_5003_50030401_1_dialog_content = "Anak bodoh... Apa yang kamu lakukan pingsan di depan pintu rumahku seperti ini? Sudah lama tidak makan enak, ya?",
  ui_story_5003_50030401_2_dialog_content = "Apakah Anda ... orang yang berjaga dua hari yang lalu?",
  ui_story_5003_50030401_3_dialog_content = "Itu benar... Kau pikir aku terlalu tua untuk melawan?",
  ui_story_5003_50030401_4_dialog_content = "Kau pasti bercanda…",
  ui_story_5003_50030401_X4_dialog_content = "<size=45>Aku melepaskanmu dengan mudah! Apakah Anda benar-benar berpikir Anda lebih baik dari saya !?</size>",
  ui_story_5003_50030401_5_dialog_content = "Hehe, tenang dan masuklah. Makan malam sudah siap.",
  ui_story_5003_50030401_6_dialog_content = "Anda membiarkan saya masuk?",
  ui_story_5003_50030401_7_dialog_content = "Bagaimana mungkin aku tidak membiarkanmu masuk.",
  ui_story_5003_50030401_X7_dialog_content = "Ini adalah hotel...",
  ui_story_5003_50030401_8_dialog_content = "dimana saya? Kamu siapa?",
  ui_story_5003_50030401_9_dialog_content = "Ini adalah sebuah dojo. Saya Sanki.",
  ui_story_5003_50030401_10_dialog_content = "Mengapa Anda mengikat saya? Apa yang akan kamu lakukan padaku?",
  ui_story_5003_50030401_11_dialog_content = "Aku harus menghentikan Anda dari memukul-mukul sekitar.",
  ui_story_5003_50030401_12_dialog_content = "Jadi, apa yang akan kamu lakukan padaku?",
  ui_story_5003_50030401_13_dialog_content = "Diam. Anda pikir saya bodoh? Saya yang mengajukan pertanyaan di sini.",
  ui_story_5003_50030401_14_dialog_content = "Baiklah, jika kamu berkata begitu... Tapi apa maksudmu ketika kamu mengatakan ini adalah dojo?",
  ui_story_5003_50030401_15_dialog_content = "Saya pikir dojo sudah lama hancur. Ini tidak mungkin tempatnya.",
  ui_story_5003_50030401_16_dialog_content = "Ini tidak bisa menjadi dojo, kan?",
  ui_story_5003_50030401_X16_dialog_content = "Hahahaha!",
  ui_story_5003_50030401_17_dialog_content = "Anda belum pernah melihat dojo. Sepertinya Anda benar-benar tidak tahu apa-apa.",
  ui_story_5003_50030401_S18_dialog_content = "Dojo hancur, tetapi sebagian masih tersembunyi di bawah Cloud Blossom Hotel.",
  ui_story_5003_50030401_S19_dialog_content = "Maaf, saya benar-benar tidak tahu apa-apa... Mengapa Anda tidak memberi tahu saya lebih banyak?",
  ui_story_5003_50030401_S20_dialog_content = "Tutup! Saya sudah mengatakan cukup! Apakah Anda pikir saya semacam orang bodoh !?",
  ui_story_5003_50030401_S21_dialog_content = "Maaf! Tidak apa-apa jika Anda tidak ingin berbicara tentang dojo. Mari kita ganti topik.",
  ui_story_5003_50030401_X18_dialog_content = "Pedangmu sangat keren. Apakah semua orang di Timur Jauh memiliki pedang?",
  ui_story_5003_50030401_19_dialog_content = "Aku menyuruhmu diam! Aku bahkan tidak mencarimu! Jadi berhentilah mencoba berbicara denganku!",
  ui_story_5003_50030401_20_dialog_content = "…!",
  ui_story_5003_50030401_21_dialog_content = "(Orang ini benar-benar memukul seseorang... Jika saya tahu... Saya akan berhenti berbicara.)",
  ui_story_5003_50030401_22_dialog_content = "PlayerName? PlayerName? Kamu ada di mana?",
  ui_story_5003_50030401_23_dialog_content = "PlayerName? Gwammy? Kamu ada di mana?",
  ui_story_5003_50030401_24_dialog_content = "Vice, apa yang terjadi?",
  ui_story_5003_50030401_25_dialog_content = "PlayerName dan Granny tidak ada di hotel... Tapi PlayerName sedang menuju ke arah ini sekarang...",
  ui_story_5003_50030401_26_dialog_content = "Mari kita lihat lagi...",
  ui_story_5003_50030401_27_dialog_content = "Keburukan! Hai! Dua kali lipat!",
  ui_story_5003_50030401_28_dialog_content = "Ada apa?",
  ui_story_5003_50030401_29_dialog_content = "Saya tidak dapat menemukan Gwammy, tetapi menemukan sebuah catatan!",
  ui_story_5003_50030401_30_dialog_content = "Keturunan Keluarga Sakura: Segera tinggalkan Cloud Mountain!",
  ui_story_5003_50030401_X30_dialog_content = "Jika tidak, sesuatu yang buruk akan terjadi pada Anda dan sesama pelancong!",
  ui_story_5003_50030401_31_dialog_content = "Selain itu, jika Anda ingin melihat PlayerName hidup kembali, pergilah ke Spa Street dan tunggu.",
  ui_story_5003_50030401_32_dialog_content = "Seseorang menyandera PlayerName!?",
  ui_story_5003_50030401_33_dialog_content = "<color=#e8d9bb>*goyang, kocok... retak, retak...*</color>",
  ui_story_5003_50030401_34_dialog_content = "(Sepertinya ada sesuatu... <color=#FFB400>gemetar</color>?)",
  ui_story_5003_50030401_35_dialog_content = "... Siapa di luar sana!?",
  ui_story_5003_50030401_36_dialog_content = "(Apakah suara itu datang dari luar...? Sanki... Dia keluar!)",
  ui_story_5003_50030401_37_dialog_content = "(Sekarang adalah kesempatan saya untuk menemukan jalan keluar dari kekacauan ini!)",
  ui_story_5003_50030401_38_dialog_content = "(Aku hampir tidak bisa bergerak... Tunggu sebentar, aku bisa memanggil seseorang dengan kemampuan psikisku!)",
  ui_story_5003_50030401_39_dialog_content = "<color=#e8d9bb>*klik...klik...shuu...*</color>",
  ui_story_5003_50030401_40_dialog_content = "(Tidak mungkin... Dia sudah kembali?)",
  ui_story_5003_50030401_41_dialog_content = "Tunggu... Itu...!",
  ui_story_5003_50030401_42_dialog_content = "Nenek!?",
  ui_story_5003_50030401_43_dialog_content = "Diam, tenang sekarang, Nak.",
  ui_story_5003_50030401_44_dialog_content = "Sedang apa kau di sini?",
  ui_story_5003_50030401_45_dialog_content = "Kita bisa membicarakannya nanti. Biarkan aku melepaskan tali ini dulu... Ayo pergi dari sini.",
  ui_story_5003_50030401_46_dialog_content = "Apa yang terjadi di sini?",
  ui_story_5003_50030401_47_dialog_content = "Anakku, aku harap kamu tidak menyalahkan Sanki atas apa yang dia lakukan. <color=#FFB400>Dia hanya ingin melindungi Cloud Mountain</color>.",
  ui_story_5003_50030401_48_dialog_content = "Melindunginya dari apa?",
  ui_story_5003_50030401_49_dialog_content = "Maaf, tapi saya tidak bisa memberi tahu Anda semua rahasia Cloud Mountain. Namun, saya dapat menjelaskan sebagian alasannya kepada Anda.",
  ui_story_5003_50030401_50_dialog_content = "Cloud Mountain dilindungi oleh penghalang luar, tetapi kedatangan Anda di sini entah bagaimana memengaruhinya, menyebabkan Eclipsites menyerang.",
  ui_story_5003_50030401_51_dialog_content = "Sanki mencoba memaksamu pergi karena kau membawa bahaya ke Gunung Awan...",
  ui_story_5003_50030401_52_dialog_content = "Aku sudah memberinya omelan. Saya harap Anda bisa memaafkannya atas apa yang dia lakukan.",
  ui_story_5003_50030401_53_dialog_content = "Tapi aku tidak mengerti... Mengapa kehadiran kita di sini mempengaruhi penghalang?",
  ui_story_5003_50030401_54_dialog_content = "Ayo keluar dulu. Aku akan menjelaskannya padamu saat kita bertemu dengan Hiiro, oke?",
  ui_story_5003_50030401_55_dialog_content = "Oke.",
  ui_story_5003_50030401_56_dialog_content = "PlayerName? Di mana kamu? Kami telah mencari Anda selama berabad-abad!",
  ui_story_5003_50030401_57_dialog_content = "Anda ... tidakkah Anda pergi ke Spa Street untuk menunggu?",
  ui_story_5003_50030401_58_dialog_content = "Jalan Spa?",
  ui_story_5003_50030401_59_dialog_content = "Sepertinya Nenek menulis pesan yang meminta kita pergi...",
  ui_story_5003_50030401_60_dialog_content = "Maaf... Tapi kupikir akan lebih baik jika kau meninggalkan Cloud Mountain.",
  ui_story_5003_50030401_61_dialog_content = "Bisakah Anda menjelaskan apa yang terjadi di sini, Nenek?",
  ui_story_5003_50030401_62_dialog_content = "Mengapa Anda membangun hotel di atas reruntuhan dojo?",
  ui_story_5003_50030401_63_dialog_content = "Yah, aku membangun hotel untuk melindungi dojo.",
  ui_story_5003_50030401_65_dialog_content = "Kurasa tidak mungkin aku bisa menyembunyikannya darimu, tapi ini hanya antara Hiiro dan orang-orang yang dia percaya.",
  ui_story_5003_50030401_66_dialog_content = "Ikut denganku, Tweety.",
  ui_story_5003_50030401_67_dialog_content = "baiklah. Jangan khawatir, Gwammy! Aku akan mengawasi stweet itu! Aku tidak akan membasahi siapa pun!",
  ui_story_5003_50030401_68_dialog_content = "Anak baik. Terima kasih.",
  ui_story_5003_50030401_69_dialog_content = "Anda seharusnya tidak kembali, Hiiro.",
  ui_story_5003_50030401_70_dialog_content = "Sakae Shigeo tidak akan mengizinkanmu untuk kembali.",
  ui_story_5003_50030401_71_dialog_content = "Nenek... Siapa kau?",
  ui_story_5003_50030401_72_dialog_content = "Ketika saya masih muda, saya pernah menjadi kepala pelayan Keluarga Sakura, dan juga seorang utusan yang memberikan informasi rahasia.",
  ui_story_5003_50030401_73_dialog_content = "Keluarga Sakura dan Keluarga Sakae adalah dua kekuatan utama yang menjaga penghalang Gunung Awan.",
  ui_story_5003_50030401_74_dialog_content = "Kedua keluarga mengundang tukang kayu paling terampil di seluruh Underwell untuk membangun ruang rahasia di dojo.",
  ui_story_5003_50030401_75_dialog_content = "Mereka menyegel sesuatu yang sangat penting di sana... Sesuatu yang mengandung kekuatan besar dan mempertahankan penghalang.",
  ui_story_5003_50030401_76_dialog_content = "Hanya ketika kedua keluarga ada di sini, darah mereka dapat digunakan untuk mengangkat segel.",
  ui_story_5003_50030401_77_dialog_content = "Tapi begitu segelnya dicabut, stabilitas penghalang akan dihancurkan oleh kekuatan besar dari \"objek penting\" ini.",
  ui_story_5003_50030401_78_dialog_content = "Dan Eclipsites akan membanjiri seperti longsoran salju.",
  ui_story_5003_50030401_79_dialog_content = "Putus asa untuk mendapatkan \"objek\" ini, <color=#FFB400>Kebencian kekuatan jahat Timur Jauh terhadap Keluarga Sakae</color> tumbuh...",
  ui_story_5003_50030401_80_dialog_content = "Pada malam naas itu, Sakae Dojo diserang.",
  ui_story_5003_50030401_81_dialog_content = "<color=#FFB400>Ruang rahasia terletak di bawah tanah</color>, dan segelnya dibasahi dengan darah keluarga Sakae.",
  ui_story_5003_50030401_82_dialog_content = "Hiiro, sebagai yang terakhir dari garis keturunan kita, hanya berdiri di sini akan mempengaruhi segel.",
  ui_story_5003_50030401_83_dialog_content = "Saya hanya kembali ke Cloud Mountain untuk menyelidiki hal-hal tentang Keluarga Sakae.",
  ui_story_5003_50030401_84_dialog_content = "<size=45>Keberadaanmu mewakili rahasia terbesar Keluarga Sakae dan Sakura</size>.",
  ui_story_5003_50030401_85_dialog_content = "Aku mengenalimu begitu aku melihatmu. Anda mengingatkan saya pada ibumu, dan nenekmu.",
  ui_story_5003_50030401_86_dialog_content = "Aku dibesarkan dengan nenekmu... tapi mereka semua sudah lama meninggal.",
  ui_story_5003_50030401_87_dialog_content = "Ini surat dari ibumu. Itu bukti bahwa apa yang saya katakan itu benar.",
  ui_story_5003_50030401_88_dialog_content = "Sekarang pergi... Menjauhlah dari sini sebelum Eclipsites melancarkan serangan lagi.",
  ui_story_5003_50030401_89_dialog_content = "Jadi selama saya pergi, Cloud Mountain akan aman?",
  ui_story_5003_50030401_90_dialog_content = "Ya.",
  ui_story_5003_50030401_91_option_content = "Mengapa Anda tidak pergi bersama kami?",
  ui_story_5003_50030401_92_dialog_content = "Maafkan aku, tapi aku tidak bisa pergi bersamamu.",
  ui_story_5003_50030401_93_dialog_content = "Saya harus tinggal di sini untuk menjaga hotel, dan ruang rahasia di bawahnya.",
  ui_story_5003_50030401_94_option_content = "Hiiro, apa yang akan kamu lakukan?",
  ui_story_5003_50030401_95_dialog_content = "Saya mengerti. Mengetahui bahwa Anda berada di sini telah membuat seluruh perjalanan ini berharga.",
  ui_story_5003_50030401_96_dialog_content = "Aku akan meninggalkan Cloud Mountain, tapi aku takut Eclipsites akan menyerang lagi...",
  ui_story_5003_50030401_97_dialog_content = "Jadi, saya ingin meminta Vice dan PlayerName untuk tinggal di sini untuk sementara waktu untuk memastikan keselamatan semua orang.",
  ui_story_5003_50030401_98_dialog_content = "Tunggu... Tanpa Colossus... Bagaimana kamu berniat pergi dari sini sendirian, Hiiro?",
  ui_story_5003_50030401_99_dialog_content = "Jangan khawatir. Aku akan menuju ke pelabuhan sendiri.",
  ui_story_5003_50030401_100_dialog_content = "Hiiro, orang-orang di sini sangat terganggu dengan kehadiranmu...",
  ui_story_5003_50030401_101_dialog_content = "Mereka mengatakan bahwa Anda membawa Eclipsites dan bencana ke Cloud Mountain.",
  ui_story_5003_50030401_102_dialog_content = "Sanki bahkan menyerang PlayerName.",
  ui_story_5003_50030401_X102_dialog_content = "Itu sebabnya saya pikir Anda semua harus pergi bersama-sama ...",
  ui_story_5003_50030401_103_dialog_content = "Saya tidak pernah berpikir perjalanan kami ke Cloud Mountain akan berakhir seperti ini ...",
  ui_story_5003_50030401_104_dialog_content = "Hush, jangan sebut PlayerName, atau Anda akan marah Komandan Hiiro.",
  ui_story_5003_50030401_105_dialog_content = "Anda tidak perlu khawatir tentang saya. Aku baik-baik saja dengan bagaimanapun perjalanan ini berakhir.",
  ui_story_5003_50030401_106_dialog_content = "Kita harus bertemu Pak Taki dan Tweety. Itu akan membuat segalanya lebih mudah bagi kita jika kita perlu menyelidiki Cloud Mountain di masa depan.",
  ui_story_5003_50030401_107_dialog_content = "Dan aku membaca surat itu. Saya percaya apa yang dikatakan Nenek itu benar.",
  ui_story_5003_50030401_108_dialog_content = "Saya belajar dari kisahnya, dan tentang sejarah keluarga saya. Perjalanan itu sepadan.",
  ui_story_5003_50030401_109_dialog_content = "Itu keren. Komandan Hiiro, Anda akhirnya bisa meninggalkan Cloud Mountain sambil tersenyum.",
  ui_story_5003_50030401_110_dialog_content = "Kenapa bisa begitu?",
  ui_story_5003_50030401_111_dialog_content = "Saya merasa seperti Anda telah stres selama ini. Aku sudah sedikit mengkhawatirkanmu...",
  ui_story_5003_50030401_112_dialog_content = "Terima kasih atas perhatian Anda.",
  ui_story_5003_50030401_113_dialog_content = "Pada awalnya, saya memiliki beberapa... kecurigaan, tetapi saya tahu bahwa semuanya akan baik-baik saja.",
  ui_story_5003_50030401_114_dialog_content = "Tuanku berkata dia tidak ingin aku kembali ke Gunung Awan, tapi dia tidak memberitahuku alasannya.",
  ui_story_5003_50030401_115_dialog_content = "Memikirkannya sekarang, mungkin dia hanya ingin melindungiku.",
  ui_story_5003_50030401_116_dialog_content = "Namun, ketika tuan saya meninggal, keinginan terakhirnya adalah agar saya \"menemukan masa depan saya di bilah Sakae\".",
  ui_story_5003_50030401_117_dialog_content = "Saya tidak mengerti apa artinya ini, tetapi setelah Sakae Blade saya mulai berubah, saya menjadi bertekad untuk kembali ke Cloud Mountain.",
  ui_story_5003_50030401_118_dialog_content = "Meskipun saya masih tidak mengerti mengapa, selama saya terus mengejar rahasia Pedang Sakae, suatu hari saya akan mengerti.",
  ui_story_5003_50030401_119_dialog_content = "Hanya saja sepertinya aku tidak akan bisa menenangkannya <color=#FFB400>getaran</color> baru saja...",
  ui_story_5003_50030401_120_dialog_content = "Tunggu.. Apa yang Anda maksud dengan \"tenangkan getarannya\"?",
  ui_story_5003_50030401_121_dialog_content = "Aku bisa merasakannya bergetar. Mungkin terdengar konyol.",
  ui_story_5003_50030401_122_dialog_content = "Tapi itulah yang terjadi. Pertama tujuh hari yang lalu, kemudian beberapa jam yang lalu bergetar lagi. Ini adalah ketiga kalinya sekarang.",
  ui_story_5003_50030401_123_dialog_content = "<color=#e8d9bb>*Brrr*</color>",
  ui_story_5003_50030401_124_dialog_content = "Dengung itu... Apakah bilahnya bergetar?",
  ui_story_5003_50030401_125_dialog_content = "Hiiro, suara ini... Sepertinya aku pernah mendengarnya di dojo.",
  ui_story_5003_50030401_126_dialog_content = "Senjata Sanki bergetar seperti Pedang Sakaemu!",
  ui_story_5003_50030401_127_dialog_content = "Tapi itu tidak mungkin... Kecuali pedangnya...",
  ui_story_5003_50030401_128_dialog_content = "Apakah juga <color=#FFB400>Pedang Sakae</color>!?",
  ui_story_5003_50030401_129_dialog_content = "Hanya api yang membakar dan darah Sakae yang bisa mengubah katana menjadi Pedang Sakae.",
  ui_story_5003_50030401_130_dialog_content = "Kekuatan jahat yang menyerang Keluarga Sakae, musuhku...",
  ui_story_5003_50030401_131_dialog_content = "<size=45>Pedang mereka berlumuran darah Sakae, dan mereka membakar rumah kami!</size>",
  ui_story_5003_50030401_X131_dialog_content = "Maksudmu, Sanki adalah salah satu musuh itu!?",
  ui_story_5003_50030501_1_dialog_content = "PlayerName, itu satu-satunya kemungkinan yang bisa kupikirkan. Dia memiliki Pedang Sakae!",
  ui_story_5003_50030501_2_dialog_content = "Guru memberi tahu saya sebelum dia meninggal bahwa pedang ini bermandikan darah Sakae.",
  ui_story_5003_50030501_3_dialog_content = "Setelah membakarnya, bilahnya akan terlahir kembali dan menjadi Pedang Sakae.",
  ui_story_5003_50030501_4_dialog_content = "Kekuatan jahat dari Timur Jauh yang membantai Keluarga Sakae... Yang kami sebut musuh kami...",
  ui_story_5003_50030501_5_dialog_content = "Pedang mereka berlumuran darah Sakae, dan mereka membakar rumah kami!",
  ui_story_5003_50030501_6_dialog_content = "Tapi Nenek pasti sudah tahu tentang Sanki, jadi kenapa dia tidak memberitahu kita?",
  ui_story_5003_50030501_7_dialog_content = "Nenek hanya seorang pengasuh keluarga, dia mengatakan kepada saya bahwa dia tidak tahu banyak tentang Sakae.",
  ui_story_5003_50030501_8_dialog_content = "Mungkin dia tidak tahu identitas asli Sanki?",
  ui_story_5003_50030501_9_dialog_content = "PlayerName, kita harus segera kembali ke Cloud Mountain!",
  ui_story_5003_50030501_10_dialog_content = "Apakah Anda tahu berapa banyak darah yang saya tumpahkan untuk hari ini?",
  ui_story_5003_50030501_11_dialog_content = "Lihat pedang ini... <color=#FFB400>Setiap kali saya mendekati segel, mereka mulai bergetar</color>! Dan mengaum!",
  ui_story_5003_50030501_12_dialog_content = "Sekarang aku hanya membutuhkan satu hal terakhir—Hiiro Keluarga Sakura!",
  ui_story_5003_50030501_13_dialog_content = "Kemudian saya akhirnya bisa memenuhi apa yang saya rindukan selama bertahun-tahun!",
  ui_story_5003_50030501_14_dialog_content = "Beraninya kau membiarkan dia pergi!?",
  ui_story_5003_50030501_15_dialog_content = "Tenang, Sanki. Mari saya jelaskan...",
  ui_story_5003_50030501_16_dialog_content = "Anda ingin saya tenang? Anda ingin saya mendengarkan lebih banyak kebohongan Anda !?",
  ui_story_5003_50030501_17_dialog_content = "Anda sengaja membawa saya pergi dan membiarkan orang itu pergi, dan kemudian Anda membiarkan Hiiro pergi! Itulah yang Anda lakukan!",
  ui_story_5003_50030501_18_dialog_content = "Kau tahu siapa aku sejak hari pertama kita bertemu! Anda telah merencanakan untuk menghentikan saya selama ini, bukan!",
  ui_story_5003_50030501_19_dialog_content = "Aku tidak berencana membunuhmu, jadi kamu pikir kamu bisa mengalahkanku? Itu saja?",
  ui_story_5003_50030501_20_dialog_content = "Tidak, dengarkan aku. Anda tidak bisa menghancurkan benda yang dilindungi segel itu. Setelah Anda menghancurkannya, Cloud Mountain akan...",
  ui_story_5003_50030501_21_dialog_content = "Diam! Saya tidak ingin mendengar sepatah kata pun dari Anda!",
  ui_story_5003_50030501_X21_dialog_content = "Anda benar-benar tidak berpikir saya akan membunuh Anda, bukan?",
  ui_story_5003_50030501_X23_dialog_content = "Beri aku darahmu.",
  ui_story_5003_50030501_22_dialog_content = "Sanki, sudah kubilang—aku bukan anggota Keluarga Sakura!",
  ui_story_5003_50030501_23_dialog_content = "Tapi aku belum mencoba darahmu!",
  ui_story_5003_50030501_X22_dialog_content = "Aku tidak akan pernah melupakan murka Underwell...",
  ui_story_5003_50030501_24_dialog_content = "Bukankah wajar jika yang kalah harus menyerahkan hidup mereka? Jika Anda kalah, Anda harus membayar harganya dengan darah.",
  ui_story_5003_50030501_25_dialog_content = "Dan begitu aku membuka pintu dan menghancurkan apa yang ada di dalamnya, balas dendamku akan selesai.",
  ui_story_5003_50030501_26_dialog_content = "Bukankah begitu... Sakae?",
  ui_story_5003_50030501_27_dialog_content = "Saya hampir lupa mengapa saya datang, tetapi Anda mengingatkan saya.",
  ui_story_5003_50030501_28_dialog_content = "Aku harus berterima kasih, Hiiro. Anda berjalan langsung ke tangan saya.",
  ui_story_5003_50030501_29_dialog_content = "Hahaha... Hahahaha...",
  ui_story_5003_50030501_30_dialog_content = "Hah... Apa yang ayahku katakan padaku pada malam dia pergi? Aku sudah lupa sekarang.",
  ui_story_5003_50030501_31_dialog_content = "Sanki! Tinggalkan dia sendiri!",
  ui_story_5003_50030501_32_dialog_content = "Hiiro!?",
  ui_story_5003_50030501_33_dialog_content = "Ha ha ha! Lihat, Nenek! Hiiro Anda telah kembali! Dia kembali sendirian!",
  ui_story_5003_50030501_34_dialog_content = "H... Hiiro! Jangan gegabah...",
  ui_story_5003_50030501_35_dialog_content = "Jika Anda memiliki dendam terhadap saya, datang pada saya. Tidak perlu bagimu untuk menyakitinya.",
  ui_story_5003_50030501_36_dialog_content = "Tentu saja... Selama kau tinggal di sini, aku akan melepaskannya.",
  ui_story_5003_50030501_37_dialog_content = "Baiklah, aku berjanji. Vice, PlayerName—lindungi Nenek.",
  ui_story_5003_50030501_38_dialog_content = "Nenek, datang padaku!",
  ui_story_5003_50030501_39_dialog_content = "Jangan khawatir! Sanki tidak akan menyakitiku! Dia bukan musuh kita! Dia hanya anak tukang kayu!",
  ui_story_5003_50030501_40_dialog_content = "Diam! Cukup kata!",
  ui_story_5003_50030501_41_dialog_content = "Hiiro! Setelah saya menggunakan darah Anda untuk membuka segel, saya akan memberitahu Anda segalanya.",
  ui_story_5003_50030501_42_dialog_content = "Aku hanya ingin kau memberitahuku dari mana pedang di tanganmu berasal... Apa kau musuh keluargaku!?",
  ui_story_5003_50030501_43_dialog_content = "Jika Anda, saya akan membalas dendam!",
  ui_story_5003_50030501_X43_dialog_content = "...",
  ui_story_5003_50030501_X44_dialog_content = "Apa lelucon!",
  ui_story_5003_50030501_X45_dialog_content = "Apa!?",
  ui_story_5003_50030501_44_dialog_content = "Anda punya keberanian masih mengoceh tentang balas dendam !?",
  ui_story_5003_50030501_45_dialog_content = "Orang-orang Underwell terjebak dalam pertarungan antara Sakae dan musuh mereka tanpa alasan, dan mereka dibantai hanya dalam satu malam...",
  ui_story_5003_50030501_46_dialog_content = "Aku mengakhiri kekuatan jahat itu. Aku membunuh semua musuh itu! Lihat saja Sakae Blades di tanganku!",
  ui_story_5003_50030501_47_dialog_content = "Pedang yang kuambil dari musuh ini adalah bukti pembalasanku! Apa yang saya lakukan adalah balas dendam nyata!",
  ui_story_5003_50030501_48_dialog_content = "Adapun Anda, saya akan mengambil hidup Anda dan menggunakannya untuk menghancurkan <size=45>sumber dari semua ini—hal di balik segel</size>!",
  ui_story_5003_50030501_49_dialog_content = "Aku tidak bisa membiarkanmu menghancurkan benda penting yang disegel di sini! Keamanan Cloud Mountain bergantung padanya!",
  ui_story_5003_50030501_50_dialog_content = "Cukup bicara! Hiiro, kamu tidak pantas mendapatkan Pedang Sakae! Sakae Shigeo, hari ini saya mengklaim pedang kedelapan saya!",
  ui_story_5003_50030501_51_dialog_content = "Nasib Gunung Awan dan Pedang Sakae ini... Keduanya tidak akan jatuh ke tanganmu!",
  ui_story_5003_50030501_52_dialog_content = "Apa yang salah? Bukankah kamu murid kebanggaan Sakae Shigeo?",
  ui_story_5003_50030501_53_dialog_content = "Ha ha ha! Anda bahkan tidak bisa melawan!?",
  ui_story_5003_50030501_54_dialog_content = "Hiiro! Fokus!",
  ui_story_5003_50030501_55_dialog_content = "Fokuskan pikiran Anda dan berikan pisau semua yang Anda miliki.",
  ui_story_5003_50030501_56_dialog_content = "Semua yang aku punya...",
  ui_story_5003_50030501_57_dialog_content = "Zakura, Sakae, kekuatan sesaat...",
  ui_story_5003_50030501_58_dialog_content = "Dan tekad yang takut mati—ini semua yang saya miliki.",
  ui_story_5003_50030501_59_dialog_content = "!!!",
  ui_story_5003_50030501_60_dialog_content = "Kamu kalah, Sanki.",
  ui_story_5003_50030501_61_dialog_content = "Hahaha... *batuk*",
  ui_story_5003_50030501_62_dialog_content = "Aku kalah... Jadi, bunuh aku...",
  ui_story_5003_50030501_63_dialog_content = "Pemenang menentukan nasib yang kalah. Ketika saya membunuh musuh saya, saya memberi tahu mereka hal yang sama.",
  ui_story_5003_50030501_66_dialog_content = "Tunggu! Hiiro! Jangan bunuh dia!",
  ui_story_5003_50030501_67_dialog_content = "Saya tahu. Dia bukan \"musuh\"ku... Katakan siapa dia, Nenek.",
  ui_story_5003_50030501_68_dialog_content = "Dia adalah putra dari tukang kayu Underwell yang membangun ruang rahasia untuk Keluarga Sakae.",
  ui_story_5003_50030501_69_dialog_content = "Keluarganya... menjadi korban pembantaian malam itu.",
  ui_story_5003_50030501_70_dialog_content = "*Batuk* Ayahku... setuju untuk membangun ruang rahasia...",
  ui_story_5003_50030501_71_dialog_content = "Sehingga saya bisa menjadi murid Sakae Dojo.",
  ui_story_5003_50030501_72_dialog_content = "Itu semua karena benda di balik segel itu! Penyebab semua kematian dan kehancuran ini!",
  ui_story_5003_50030501_74_dialog_content = "Tidak, objek yang disegel di sini terlalu penting untuk Cloud Mountain, jadi semua orang mengorbankan segalanya untuk melindunginya...",
  ui_story_5003_50030501_75_dialog_content = "Cukup omong kosong ini! Lakukan!",
  ui_story_5003_50030501_76_dialog_content = "Baiklah...",
  ui_story_5003_50030501_77_dialog_content = "...",
  ui_story_5003_50030501_S77_dialog_content = "Anda hanya memotong rambut saya?",
  ui_story_5003_50030501_X77_dialog_content = "Mengapa kau melakukan ini!? Mengapa Anda tidak akan menghabisi saya?",
  ui_story_5003_50030501_X78_dialog_content = "aku sudah menghabisimu...",
  ui_story_5003_50030501_78_dialog_content = "\"Kamu\" sudah mati— \"kamu\" yang terobsesi dengan balas dendam telah dikalahkan.",
  ui_story_5003_50030501_79_dialog_content = "Kuharap kau bisa melupakannya, dan mengakhirinya... Menyerahlah pada ide menghancurkan segel ini.",
  ui_story_5003_50030501_80_dialog_content = "Aku lebih suka kau membunuhku daripada menjadikanku pembelot pengecut sepertimu dan Sakae Shigeo!",
  ui_story_5003_50030501_81_dialog_content = "Ada saat ketika saya tidak mengerti bagaimana dia bisa melarikan diri dalam situasi seperti itu.",
  ui_story_5003_50030501_82_dialog_content = "Tapi Sakae Shigeo... Tuanku... dia tidak pernah takut menatap kematian di wajahnya.",
  ui_story_5003_50030501_X82_dialog_content = "Dia mencoba membawaku, \"kunci\" segel, pergi dari sini.",
  ui_story_5003_50030501_83_dialog_content = "Tuan, apakah luka lamamu terbuka kembali?!",
  ui_story_5003_50030501_84_dialog_content = "Eclipsites akan segera tiba, dan tidak ada yang bisa mempertahankan jalan menuju tempat perlindungan kecuali kita.",
  ui_story_5003_50030501_85_dialog_content = "Tapi lukaku terlalu parah bagiku untuk terus berjuang...",
  ui_story_5003_50030501_X85_dialog_content = "Sudah waktunya bagi saya untuk mati.",
  ui_story_5003_50030501_86_dialog_content = "Hiiro, setelah aku mati, ambil pedangku... Itu akan menjadi Pedang Sakae sejati.",
  ui_story_5003_50030501_87_dialog_content = "Api yang membakar dan darah Sakae... akan membuat pedang ini sangat kuat. Pedang Sakae ini...",
  ui_story_5003_50030501_88_dialog_content = "Ini akan membuat Anda sangat kuat. Ini akan memberi Anda kekuatan untuk mengalahkan Eclipsites.",
  ui_story_5003_50030501_89_dialog_content = "Saya harap Anda dapat melihat masa depan Anda yang hebat di Sakae Blade.",
  ui_story_5003_50030501_90_dialog_content = "Guru berharap saya bisa melihat masa depan di Pedang Sakae.",
  ui_story_5003_50030501_91_dialog_content = "Tapi aku tidak tahu apa \"masa depan\" itu.",
  ui_story_5003_50030501_92_dialog_content = "Aku tidak mengerti sampai aku melihatmu.",
  ui_story_5003_50030501_93_dialog_content = "Apa maksudmu \"sampai kau melihatku\"?",
  ui_story_5003_50030501_94_dialog_content = "Seperti Anda, saya kembali ke Cloud Mountain karena kebencian.",
  ui_story_5003_50030501_95_dialog_content = "Tapi sekarang aku tahu segalanya.",
  ui_story_5003_50030501_96_dialog_content = "Objek tersegel mempertahankan penghalang yang melindungi Cloud Mountain. Semua orang mati melindungi Cloud Mountain.",
  ui_story_5003_50030501_97_dialog_content = "Jadi, saya tidak bisa membiarkan Anda memecahkan segel dan menghancurkan apa yang ada di sana.",
  ui_story_5003_50030501_98_dialog_content = "Tapi aku tidak akan pernah membunuhmu.",
  ui_story_5003_50030501_102_dialog_content = "Saya mengenali teknik Anda. Kami dari sekolah yang sama.",
  ui_story_5003_50030501_103_dialog_content = "...",
  ui_story_5003_50030501_104_dialog_content = "Ayah! Akankah Sakae Dojo benar-benar menerima saya?",
  ui_story_5003_50030501_105_dialog_content = "Tentu saja! Mulai minggu depan, kamu akan menjadi murid Sakae Dojo!",
  ui_story_5003_50030501_106_dialog_content = "Keluarga Sakae luar biasa! Mereka melindungi semua Cloud Mountain. Pastikan Anda belajar keras setelah Anda bergabung dengan mereka!",
  ui_story_5003_50030501_107_dialog_content = "Oke, Ayah! Aku akan melakukan yang terbaik!",
  ui_story_5003_50030501_108_dialog_content = "Matahari telah terbit. Sudah waktunya bagi saya untuk pergi ke Cloud Mountain. Aku akan menunggumu di dojo...",
  ui_story_5003_50030501_109_dialog_content = "Nah, matahari sudah terbit. Sudah waktunya bagi saya untuk pergi.",
  ui_story_5003_50030501_X109_dialog_content = "Kehadiran saya di sini akan mempengaruhi stabilitas segel, jadi saya tidak boleh kembali ke Cloud Mountain.",
  ui_story_5003_50030501_X110_dialog_content = "Saya harap tidak ada yang akan mengetahui apa yang disegel di sini dan Cloud Mountain akhirnya akan mengetahui kedamaian.",
  ui_story_5003_50030501_X111_dialog_content = "Jika ada orang lain yang ingin membuka segelnya, mereka harus mengambil darahku terlebih dahulu.",
  ui_story_5003_50030501_X112_dialog_content = "Bagaimana dengan saya...?",
  ui_story_5003_50030501_X113_dialog_content = "Anda dapat mencoba mengambil darah saya, berapa kali pun Anda mau.",
  ui_story_5003_50030501_X114_dialog_content = "Tapi karena kita murid Sakae Dojo... Aku hanya akan menganggapnya sebagai \"sparring\".",
  ui_story_5003_50030501_110_dialog_content = "Hmm... Sepertinya Sanki tidak mau datang dan mengantarmu pergi.",
  ui_story_5003_50030501_111_dialog_content = "Tidak apa-apa, aku tidak mengharapkannya.",
  ui_story_5003_50030501_112_dialog_content = "Saya memberinya pelajaran yang sulit dengan harapan dia akan menyerah pada balas dendamnya, jadi saya tidak bisa menyalahkannya karena menyimpan dendam di hatinya ...",
  ui_story_5003_50030501_113_dialog_content = "Jangan khawatir. Saya tidak berpikir dia membenci Anda.",
  ui_story_5003_50030501_S113_dialog_content = "Pada hari dia mengetahui tentang ruang rahasia di bawah hotel... Aku telah merencanakan untuk menjaga pintu masuk dengan nyawaku.",
  ui_story_5003_50030501_S114_dialog_content = "Tapi dia tiba-tiba meletakkan senjatanya dan berhenti mencoba memaksa masuk.",
  ui_story_5003_50030501_S115_dialog_content = "Setelah itu, dia mulai berkeliaran di sekitar sini, terus-menerus bertanya bagaimana keadaan di hotel.",
  ui_story_5003_50030501_S116_dialog_content = "Perlahan-lahan, dia membuka diri kepada saya tentang hidupnya dan bahkan akan membantu Tweety dengan tugas-tugasnya.",
  ui_story_5003_50030501_S117_dialog_content = "Ketika saya mengatakan kepadanya bahwa tidak ada keturunan Keluarga Sakura yang tersisa, dan segel itu tidak bisa lagi dipatahkan...",
  ui_story_5003_50030501_S118_dialog_content = "Aku melihatnya menghela napas lega.",
  ui_story_5003_50030501_S119_dialog_content = "Pada saat itu, saya tiba-tiba merasa bahwa mungkin dia juga membutuhkan alasan untuk menyerah di jalan balas dendamnya.",
  ui_story_5003_50030501_S120_dialog_content = "Aku menyembunyikan keberadaanmu darinya dan tidak memberitahunya rahasia segel. Itu semua salahku.",
  ui_story_5003_50030501_S121_dialog_content = "Saya tahu bahwa Anda hanya ingin melindungi rahasia segel. Ini bukan salah siapa-siapa.",
  ui_story_5003_50030501_114_dialog_content = "Gwammy, Sanki ingin berendam di air panas. Saya mengatakan kepadanya bahwa itu belum lelah, tetapi dia melompat untuk membersihkannya sendiri.",
  ui_story_5003_50030501_115_dialog_content = "Sanki sedang memegang seikat pedang ketika dia melompat...",
  ui_story_5003_50030501_116_dialog_content = "Hehe, saya pikir dia hanya ingin membersihkannya. Dia akan segera keluar bersama mereka.",
  ui_story_5003_50030501_117_dialog_content = "Dia adalah anak yang baik dengan hati yang baik, dan dia peduli dengan Gunung Awan, tetapi hidupnya tidak mudah, dan pikirannya sedikit bingung.",
  ui_story_5003_50030501_S122_dialog_content = "Aku tidak pernah percaya dia akan benar-benar menyakiti kita.",
  ui_story_5003_50030501_118_dialog_content = "Meskipun saya percaya pada penilaian Anda, saya harap Anda tidak akan pernah lagi dipaksa untuk menghadapi masalah berbahaya seperti itu sendirian.",
  ui_story_5003_50030501_119_dialog_content = "Tweety, Taki, dan saya—jika Anda perlu bicara, Anda punya teman yang bisa Anda percaya.",
  ui_story_5003_50030501_120_dialog_content = "Adapun Sanki, Anda harus berbicara dengan dia tentang rencananya. Saya khawatir setelah liburan Tweety berakhir, hotel akan ditinggalkan.",
  ui_story_5003_50030501_121_dialog_content = "Mungkin Sanki bisa tinggal di sini dan membantu Anda dengan hotel.",
  ui_story_5003_50030501_122_dialog_content = "Jangan khawatir tentang apakah dia menyelinap ke dojo lagi. Jika terjadi sesuatu, Pedang Sakae akan memberitahuku.",
  ui_story_5003_50030501_123_dialog_content = "Baiklah, anakku. Jangan khawatir.",
  ui_story_5003_50030501_124_dialog_content = "Yah, saya tidak pernah berharap Anda akan membawa banyak drama ini dengan Anda ...",
  ui_story_5003_50030501_125_dialog_content = "Mister Taki, apa yang Anda kagumi tentang kicau?",
  ui_story_5003_50030501_126_dialog_content = "Tidak, tidak, jangan pedulikan aku. Aku hanya sedang berlibur.",
  ui_story_5003_50030501_127_dialog_content = "Selamat tinggal.",
  ui_story_5003_50030501_128_dialog_content = "Pak Taki pakan sebelum Hiiwo??",
  ui_story_5003_50030501_129_dialog_content = "Saya pikir dia menuju ke arah yang sama seperti sebelumnya. Dia menuju ke Spa Street.",
  ui_story_5003_50030501_130_dialog_content = "Mungkin dia sedang ada urusan, seperti biasa?",
  ui_story_5003_50030501_131_dialog_content = "berat! Kedengarannya seperti dia!",
  ui_story_5003_50030501_132_dialog_content = "Ini sudah larut. Aku harus pergi juga.",
  ui_story_5003_50030501_133_dialog_content = "Hati-hati, semuanya.",
  ui_story_5003_50030501_134_dialog_content = "Hai! Hiiro!",
  ui_story_5003_50030501_135_dialog_content = "Tidakkah Anda menginginkan Pedang Sakae Anda?",
  ui_story_5003_50030501_136_dialog_content = "Pedang Sakae saya tidak pernah meninggalkan sisi saya. Saya tidak mengerti apa yang Anda bicarakan.",
  ui_story_5003_50030501_137_dialog_content = "Saya memiliki tujuh dari mereka di sini. Tidakkah kamu menginginkan mereka?",
  ui_story_5003_50030501_138_dialog_content = "Tentu saja tidak. Bagaimana mungkin aku bisa mengambil Pedang Sakaemu?",
  ui_story_5003_50030501_139_dialog_content = "<size=30>\"Aku harap kamu bisa melihat masa depanmu yang hebat di depan di Pedang Sakae\"...</size>",
  ui_story_5003_50030501_140_dialog_content = "Hah? Apa katamu?",
  ui_story_5003_50030501_141_dialog_content = "Jangan khawatir, aku hanya berbicara pada diriku sendiri.",
  ui_story_5003_50030501_142_dialog_content = "Sanki, sesama muridku, kamu harus menjaga dojo dengan Nenek.",
  ui_story_5003_50030501_143_dialog_content = "Aku…",
  ui_story_5003_50030501_144_dialog_content = "Saya percaya kamu.",
  ui_story_5003_50030501_145_dialog_content = "Apa pun! Jika Anda tidak menginginkan bilahnya, lupakan saja!",
  ui_story_5003_50030501_146_dialog_content = "Jika Anda ingin menjaganya, jaga saja sendiri! Bagaimanapun, semuanya sudah berakhir untukku!",
  ui_story_5003_50030501_147_dialog_content = "Dah!",
  ui_story_5003_50030501_148_dialog_content = "Orang ini...",
  ui_story_5003_50030501_149_dialog_content = "Saya akan mengatakan pikirannya lebih dari sedikit bingung ...",
  ui_story_5003_50030501_150_dialog_content = "Komandan Hiiro, PlayerName biasanya menyebut orang seperti ini sebagai tsundere.",
  ui_story_5003_50030501_151_dialog_content = "Vice, jangan mengubah topik pembicaraan saya tiba-tiba!",
  ui_story_5003_50030501_152_dialog_content = "Vice, PlayerName...",
  ui_story_5003_50030501_153_dialog_content = "Maaf, Komandan! Kami tahu ini bukan waktu yang tepat untuk bercanda!",
  ui_story_5003_50030501_154_dialog_content = "Bukan itu yang akan saya katakan.",
  ui_story_5003_50030501_155_dialog_content = "Terima kasih atas bantuan dan kepercayaan Anda kepada saya. Ayo pergi. Kita harus kembali.",
  ui_story_5003_50030501_156_dialog_content = "Baiklah, Soroz siap untuk pindah!",
  ui_story_5003_50030501_157_dialog_content = "Perjalanan yang aman, anak-anakku.",
  ui_story_5003_50030501_158_dialog_content = "Sampai jumpa! Jangan lupa untuk mengirimkan surat kepada kami melalui Couwier Union!",
  ui_story_5003_50030501_159_dialog_content = "Tentu saja, saya akan meminta seseorang dari Serikat Kurir untuk mengirimi Anda surat.",
  ui_story_5003_50030501_160_dialog_content = "Selamat tinggal, Gunung Awan."
}
